import re,subprocess,sys,os
WT='/home/user/fortress-landing-32'; BASE='db352c177'
def git(*a):
    return subprocess.run(['git','-C',WT]+list(a),capture_output=True,text=True,errors='replace').stdout
changed=[f for f in git('diff','--name-only',BASE,'HEAD').split('\n') if f and not f.startswith('explorations/')]
bybase={}
for f in changed: bybase.setdefault(os.path.basename(f),[]).append(f)
def lines_at(rev,f):
    return git('show',f'{rev}:{f}').split('\n')
cache={}
def L(rev,f):
    k=(rev,f)
    if k not in cache: cache[k]=lines_at(rev,f) if rev else open(os.path.join(WT,f),errors='replace').read().split('\n')
    return cache[k]
for rec in ['FACTS.md','POSITIONS.md']:
    for line in open(os.path.join(WT,'explorations/coordinator',rec)):
        m=re.match(r'- ([FP]-\d+) ',line)
        if not m: continue
        eid=m.group(1)
        # tokens in backticks
        cur=None
        for tok in re.findall(r'`([^`]+)`',line):
            mm=re.match(r'^(?:([A-Za-z0-9_./$-]+\.(?:fss|fsi|scala|java|tex|rats|ast)))?:(\d+)(?:-(\d+))?$',tok)
            if not mm:
                m2=re.match(r'^([A-Za-z0-9_./$-]+\.(?:fss|fsi|scala|java|tex|rats|ast))$',tok)
                if m2: cur=m2.group(1)
                elif re.match(r'^\.(fsi|fss):',tok) and cur:
                    ext=tok.split(':')[0]; cur2=re.sub(r'\.(fss|fsi)$',ext,cur)
                    mm=re.match(r'^\.(?:fsi|fss):(\d+)(?:-(\d+))?$',tok)
                    if mm:
                        cur=cur2; a=int(mm.group(1)); b=int(mm.group(2) or a)
                    else: continue
                else: continue
                if not mm: continue
            else:
                if mm.group(1): cur=mm.group(1)
                a=int(mm.group(2)); b=int(mm.group(3) or a)
            if not cur: continue
            if ':' in cur: continue
            cands=bybase.get(os.path.basename(cur),[])
            cands=[c for c in cands if c.endswith(cur) ] or ([c for c in cands] if '/' not in cur else [])
            if len(cands)!=1: 
                if cands: print(eid,'AMBIG',cur,cands)
                continue
            f=cands[0]
            old=L(BASE,f); new=L(None,f)
            def get(x,i): return x[i-1].strip() if 0<i<=len(x) else None
            sa=get(old,a)==get(new,a); sb=get(old,b)==get(new,b)
            if sa and sb: continue
            # is cited new text found at base at a different line (i.e. moved correctly)?
            na=get(new,a); nb=get(new,b)
            oa=[i+1 for i,x in enumerate(old) if x.strip()==na] if na else []
            ob=[i+1 for i,x in enumerate(old) if x.strip()==nb] if nb else []
            print(eid,f'{os.path.basename(f)}:{a}-{b}','new-start-in-base@',oa[:4],'new-end-in-base@',ob[:4],'| new:',(na or '')[:70])
EOF
python3 -I cites.py | head -150

